from sympy import Rational, floor, gcd
def saw(x):
    return 0 if x == floor(x) else x - floor(x) - Rational(1,2)
def s(h,k):
    return sum(saw(Rational(r,k))*saw(Rational(h*r,k)) for r in range(1,k))
def P(m,n):
    return 6*n*s(m,n)
ok = all(P(m,n) == P(m,n % m) - (n//m)*P(n % m, m) + Rational(n//m,2)*(n + n % m - 3*m) for m in range(2,25) for n in range(m+1,60) if gcd(m,n) == 1 and n % m != 0)
